 29	/**
 30	 * Builds a project generation URI from a {@link ProjectGenerationRequest} and service
 31	 * metadata.
 32	 *
 33	 * @author Stephane Nicoll
 34	 * @author Eddú Meléndez
 35	 */
 36	class ProjectGenerationRequestUrlFactory {
 37	
 38		URI create(ProjectGenerationRequest request, InitializrServiceMetadata metadata) {
 39			try {
 40				URIBuilder builder = new URIBuilder(request.getServiceUrl());
 41				ProjectType projectType = determineProjectType(request, metadata);
 42				builder.setPath(resolvePath(builder.getPath(), projectType.getAction()));
 43				setParameter(builder, "dependencies", request.getDependencies().isEmpty()
 44						? null : StringUtils.collectionToCommaDelimitedString(request.getDependencies()));
 45				setParameter(builder, "groupId", request.getGroupId());
 46				setParameter(builder, "artifactId", resolveArtifactId(request));
 47				setParameter(builder, "version", request.getVersion());
 48				setParameter(builder, "name", request.getName());
 49				setParameter(builder, "description", request.getDescription());
 50				setParameter(builder, "packageName", request.getPackageName());
 51				builder.setParameter("type", projectType.getId());
 52				setParameter(builder, "packaging", request.getPackaging());
 53				setParameter(builder, "javaVersion", request.getJavaVersion());
 54				setParameter(builder, "language", request.getLanguage());
 55				setParameter(builder, "bootVersion", request.getBootVersion());
 56				return builder.build();
 57			}
 58			catch (URISyntaxException ex) {
 59				throw new ReportableException("Invalid service URL (" + ex.getMessage() + ")");
 60			}
 61		}
 62	
 63		private ProjectType determineProjectType(ProjectGenerationRequest request, InitializrServiceMetadata metadata) {
 64			if (request.getType() != null) {
 65				ProjectType result = metadata.getProjectTypes().get(request.getType());
 66				if (result == null) {
 67					throw new ReportableException(
 68							("No project type with id '" + request.getType() + "' - check the service capabilities (--list)"));
 69				}
 70				return result;
 71			}
 72			if (request.isDetectType()) {
 73				Map<String, ProjectType> types = new HashMap<>(metadata.getProjectTypes());
 74				if (request.getBuild() != null) {
 75					filter(types, "build", request.getBuild());
 76				}
 77				if (request.getFormat() != null) {
 78					filter(types, "format", request.getFormat());
 79				}
 80				if (types.size() == 1) {
 81					return types.values().iterator().next();
 82				}
 83				if (types.isEmpty()) {
 84					throw new ReportableException("No type found with build '" + request.getBuild() + "' and format '"
 85							+ request.getFormat() + "' check the service capabilities (--list)");
 86				}
 87				throw new ReportableException("Multiple types found with build '" + request.getBuild() + "' and format '"
 88						+ request.getFormat() + "' use --type with a more specific value " + types.keySet());
 89			}
 90			ProjectType defaultType = metadata.getDefaultType();
 91			if (defaultType == null) {
 92				throw new ReportableException(("No project type is set and no default is defined. "
 93						+ "Check the service capabilities (--list)"));
 94			}
 95			return defaultType;
 96		}
 97	
 98		private @Nullable String resolveArtifactId(ProjectGenerationRequest request) {
 99			if (request.getArtifactId() != null) {
100				return request.getArtifactId();
101			}
102			if (request.getOutput() != null) {
103				int i = request.getOutput().lastIndexOf('.');
104				return (i != -1) ? request.getOutput().substring(0, i) : request.getOutput();
105			}
106			return null;
107		}
108	
109		private static void filter(Map<String, ProjectType> projects, String tag, String tagValue) {
110			projects.entrySet().removeIf((entry) -> !tagValue.equals(entry.getValue().getTags().get(tag)));
111		}
112	
113		private String resolvePath(@Nullable String path, String action) {
114			StringBuilder resolvedPath = new StringBuilder();
115			if (path != null) {
116				resolvedPath.append(path);
117			}
118			resolvedPath.append(action);
119			return resolvedPath.toString();
120		}
121	
122		private void setParameter(URIBuilder builder, String name, @Nullable String value) {
123			if (value != null) {
124				builder.setParameter(name, value);
125			}
126		}
